def check_3x3_pattern(grid, r, c):
    if r < 1 or r >= len(grid)-1 or c < 1 or c >= len(grid[0])-1:
        return None

    # Extract 3x3 around cell (r,c) excluding center
    top = grid[r-1][c-1], grid[r-1][c], grid[r-1][c+1]
    mid = grid[r][c-1],           grid[r][c+1]
    bot = grid[r+1][c-1], grid[r+1][c], grid[r+1][c+1]

    return (top, mid, bot)

