# Fix the parser to handle multi-line grids
import os,glob,re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')

    matches = list(re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t))
    G = {}
    pos = 0

    for m in matches:
        k, h, w = m[1], int(m[2]), int(m[3])

        # Extract the next h lines starting after this marker
        start_pos = m.end()
        lines = []
        i = start_pos
        while len(lines) < h and i < len(t):
            if t[i] == '\n':
                end_newline = i + 1
                if end_newline < len(t) and t[end_newline:i] != '' or i > start_pos:
                    break
                else:
                    lines.append(t[start_pos:end_newline-1] if start_pos < end_newline-1 else "")
                    i = end_newline
            elif t[i] == ' ':
                # Find space-delimited number
                num_start = i
                while i < len(t) and t[i] in '0123456789 ':
                    i += 1
                lines.append(t[num_start:i].strip())
            else:
                i += 1

        # Actually let's use a simpler approach - just split by newline and take lines that have numbers
        rest_of_file = t[m.end():]
        grid_lines = []
        for line in rest_of_file.split('\n'):
            if line.strip():
                grid_lines.append([int(x) for x in line.split()])
            else:
                break  # Stop at empty line

        # Take exactly h rows
        if len(grid_lines) >= h:
            G[k] = grid_lines[:h]
        else:
            G[k] = grid_lines

    return G

