# New hypothesis: Only change fill cells if they form a CONTINUOUS SEGMENT 
# bounded by boundaries on BOTH ENDS in the SAME DIRECTION (horizontal OR vertical)
# But DON'T consider grid edges as boundaries!

def solve_enclosed_segments(grid):
    """Fill cells that form continuous segments bounded by boundaries on both ends (horiz or vert)"""
    rows = len(grid)
    cols = len(grid[0])

    count_dict = {}
    for row in grid:
        for cell in row:
            count_dict[cell] = count_dict.get(cell, 0) + 1

    sorted_vals = sorted(count_dict.items(), key=lambda x: x[1])
    boundary_val = sorted_vals[0][0]
    fill_val = sorted_vals[1][0]
    marker_val = (fill_val + boundary_val) // 4

    result = [row[:] for row in grid]
    changed_set = set()

    # Check horizontal segments
    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r][c] == fill_val:
                start = c
                while c < cols and grid[r][c] == fill_val:
                    c += 1
                end = c  # exclusive

                # Segment is from start to end-1
                # Has boundary on left?
                has_left = (start > 0 and grid[r][start-1] == boundary_val)
                # Has boundary on right?
                has_right = (end < cols and grid[r][end] == boundary_val)

                # Only change if bounded on BOTH ends
                if has_left and has_right:
                    for k in range(start, end):
                        result[r][k] = marker_val
                        changed_set.add((r, k))
            else:
                c += 1

    # Check vertical segments  
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == fill_val:
                start = r
                while r < rows and grid[r][c] == fill_val:
                    r += 1
                end = r  # exclusive

                has_up = (start > 0 and grid[start-1][c] == boundary_val)
                has_down = (end < rows and grid[end][c] == boundary_val)

                if has_up and has_down:
                    for kr in range(start, end):
                        result[kr][c] = marker_val
                        changed_set.add((kr, c))
            else:
                r += 1

    print(f"Strict enclosure - Changed {len(changed_set)} cells")
    return result

