def find_rectangular_regions(grid):
    """Find all rectangles where corners are the minority value"""
    rows = len(grid)
    cols = len(grid[0])

    count_dict = {}
    for row in grid:
        for cell in row:
            count_dict[cell] = count_dict.get(cell, 0) + 1

    sorted_vals = sorted(count_dict.items(), key=lambda x: x[1])
    minority_val = sorted_vals[0][0]

    # Collect all minority value positions
    minority_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == minority_val:
                minority_cells.append((r,c))

    # Find rectangles (4 corners) among these positions
    rectangles = []
    seen = set()

    for i, (r1, c1) in enumerate(minority_cells):
        for j in range(i+1, len(minority_cells)):
            r2, c2 = minority_cells[j]

            # Check if these can be opposite corners of rectangle  
            # They must share either same row or column to be adjacent
            # Or they're diagonal and the other two corners exist

            # Check all possible pairings
            pairs = [(r1, c1), (r2, c2)]

            # Try each as diagonal pair
            for dr in [r1, r2]:
                for dc in [c1, c2]:
                    if grid[dr][dc] != minority_val:
                        continue

                    # Check for a third point at same row
                    if dr < r2:
                        for cr in range(dr+1, r2):
                            if grid[cr][dc] == minority_val and grid[cr][c2] == minority_val:
                                # Found a rectangle!
                                tl = (dr, min(dc, c2))
                                tr = (dr, max(dc, c2))
                                bl = (cr, min(dc, c2))
                                br = (cr, max(dc, c2))
                                rects_key = tuple(sorted([tl,tr,bl,br]))
                                if rects_key not in seen:
                                    seen.add(rects_key)
                                    rectangles.append((tl, tr, bl, br))
                    else:
                        for cr in range(r2, dr-1, -1):
                            if grid[cr][dc] == minority_val and grid[cr][c2] == minority_val:
                                tl = (dr, min(dc, c2))
                                tr = (dr, max(dc, c2))
                                bl = (cr, min(dc, c2))
                                br = (cr, max(dc, c2))
                                rects_key = tuple(sorted([tl,tr,bl,br]))
                                if rects_key not in seen:
                                    seen.add(rects_key)
                                    rectangles.append((tl, tr, bl, br))

    return rectangles, minority_val

