def solve_iterative(grid, max_iterations=10):
    rows = len(grid)
    cols = len(grid[0])

    count_dict = {}
    for row in grid:
        for cell in row:
            count_dict[cell] = count_dict.get(cell, 0) + 1

    sorted_vals = sorted(count_dict.items(), key=lambda x: x[1])
    minority_val = sorted_vals[0][0]
    majority_val = sorted_vals[1][0]
    marker_val = (majority_val + minority_val) // 4

    result = [row[:] for row in grid]

    for iteration in range(max_iterations):
        changed_in_step = False

        # Check each cell
        for r in range(rows):
            for c in range(cols):
                curr = grid[r][c]  # Original value

                # Horizontal check: bounded by minority on both ends
                h_enclosed = False
                if curr == majority_val:
                    start = c
                    while c < cols and grid[r][c] == majority_val:
                        c += 1
                    end = c
                    has_left = (start > 0 and grid[r][start-1] == minority_val)
                    has_right = (end < cols and grid[r][end] == minority_val)
                    if has_left and has_right:
                        h_enclosed = True

                    c = end + 1  # Continue scanning

                # Vertical check: bounded by minority on both ends
                v_enclosed = False
                r_temp = r
                while r_temp >= 0 and grid[r_temp][c] == majority_val:
                    r_temp -= 1
                r_start = r_temp + 1

                r_temp = r
                while r_temp < rows and grid[r_temp][c] == majority_val:
                    r_temp += 1
                r_end = r_temp

                has_up = (r_start > 0 and grid[r_start-1][c] == minority_val)
                has_down = (r_end < rows and grid[r_end][c] == minority_val)

                if has_up and has_down:
                    v_enclosed = True

                # Change if EITHER horizontal OR vertical is enclosed
                if (h_enclosed or v_enclosed) and curr == majority_val:
                    result[r][c] = marker_val
                    changed_in_step = True

        # After step, check for swaps
        for r in range(rows):
            for c in range(cols):
                if result[r][c] == minority_val:
                    # Check all 4 neighbors
                    neighbors = []
                    if r > 0: neighbors.append(result[max(0,r-1)][c])
                    if r < rows-1: neighbors.append(result[min(rows-1,r+1)][c])
                    if c > 0: neighbors.append(result[r][max(0,c-1)])
                    if c < cols-1: neighbors.append(result[r][min(cols-1,c+1)])

                    # All same type -> swap
                    if all(n == minority_val for n in neighbors):
                        result[r][c] = majority_val
                    elif all(n == majority_val for n in neighbors):
                        result[r][c] = majority_val  # Already 6
                        pass

        if not changed_in_step:
            break

    return result

